  package    net . masterthought . cucumber . json ;   import     com . fasterxml . jackson . annotation . JsonProperty ;  import      net . masterthought . cucumber . json . support . Status ;  import     net . masterthought . cucumber . util . Util ;  import      net . masterthought . cucumber . json . support . Durationable ;   public class Result  implements  Durationable  {   private final Status  status =  Status . UNDEFINED ;    @ JsonProperty  ( "error_message" ) private final String  errorMessage = null ;   private final Long  duration = 0L ;   public Status getStatus  ( )  {  return status ; }   public  @ Override  long getDuration  ( )  {  return duration ; }   public String getErrorMessage  ( )  {  return errorMessage ; }   public final String getErrorMessageTitle  ( )  {  return   errorMessage . split  ( "[\\r\\n]+" ) [ 0 ] ; }    @ Override public String getFormattedDuration  ( )  {  return  Util . formatDuration  ( duration ) ; } }